// A generated 1x1 solid-color JPEG, not a user image.
const base64 = '';

export function jpegBytes(): Uint8Array<ArrayBuffer> {
  return Uint8Array.from(atob(base64), (character) => character.charCodeAt(0));
}

/** Alter only frame dimensions to exercise header validation, not decoding. */
export function jpegFrame(width: number, height: number): Uint8Array<ArrayBuffer> {
  const bytes = jpegBytes();
  const offset = bytes.findIndex((byte, index) => byte === 0xff && bytes[index + 1] === 0xc0);
  bytes[offset + 5] = height >> 8; bytes[offset + 6] = height & 255;
  bytes[offset + 7] = width >> 8; bytes[offset + 8] = width & 255;
  return bytes;
}
